    }
</code></pre>

Q: Flutter passing data up through stateless widget A: <pre><code>import 'package:flutter/material.dart';

void main() {
  runApp(MyApp());
}

class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: ServiceListScreen(),
    );
  }
}

class ServiceListScreen extends StatelessWidget {
  final List&lt;Service&gt; services = [
    Service('Light Repair', 150),
    Service('Fan Repair', 100),
    Service('Wiring', 200),
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Our Services')),
      body: ListView.builder(
        itemCount: services.length,
        itemBuilder: (context, index) {
          final service = services[index];
          return ListTile(
            title: Text(service.name),
            subtitle: Text('Price: \$${service.price}'),
            trailing: IconButton(
              icon: Icon(Icons.phone),
              onPressed: () {
                // यहाँ कॉल करने का कोड आएगा (यहाँ आप प्लगइन जोड़ सकते हैं)
                // जैसे url_launcher पैकेज का इस्तेमाल करके
              },
            ),
          );
        },
      ),
    );
  }
}

class Service {
  final String name;
  final int price;

  Service(this.name, this.price);
}
</code></pre>
